def per_doc_token_auroc(docs: list, tok_scores: np.ndarray) -> dict:
    """Alternative A5 aggregation: mean of per-document token AUROC (macro).

    A document contributes only if it contains both anomalous and normal tokens
    (AUROC undefined otherwise).  Primary reported metric stays the pooled
    (micro) AUROC used by the authors' demo code: roc_auc_score(z_test, score).
    """
    y_all, s_all, used = [], [], 0
    off = 0
    for d in docs:
        k = len(d["token_labels"])
        y = np.asarray(d["token_labels"], dtype=int)
        s = np.asarray(tok_scores[off:off + k], dtype=np.float64)
        off += k
        if 0 < y.sum() < len(y):
            y_all.append(y)
            s_all.append(s)
            used += 1
    assert off == len(tok_scores)
    if not used:
        return {"auroc_macro_per_doc": None, "n_docs_used": 0, "n_docs_total": len(docs)}
    aucs = [roc_auc_score(y, s) for y, s in zip(y_all, s_all)]
    return {"auroc_macro_per_doc": float(np.mean(aucs)), "n_docs_used": used,
            "n_docs_total": len(docs)}


