"""Mine the authors' demo.ipynb frozen outputs for printed metric values.

Reads only the released notebook: any AUROC/AUPRC the authors themselves printed
anchors the metric definition (pooling, distance, aggregation) to their code.
"""
import json
import re

nb = json.load(open("repo/demo.ipynb", encoding="utf-8"))
pat = re.compile(
    r"(AUROC|AUPRC|ROC|PRC|auroc|auprc|roc_auc|average_precision|"
    r"precision|recall|score|Token-level|Document-level|document|token)[^\n]*")
seen = set()
for i, c in enumerate(nb["cells"]):
    if c["cell_type"] != "code":
        continue
    # metrics printed by code cells' *source* too (scoring code)
    src = "".join(c["source"])
    for line in src.splitlines():
        if re.search(r"roc_auc|average_precision|AUROC|AUPRC|decision_function|mean\(|aggregat", line):
            print(f"CODE cell{i}: {line.strip()}")
    for o in c.get("outputs", []):
        txt = []
        if o.get("output_type") == "stream":
            txt = o.get("text", [])
        else:
            tp = o.get("data", {}).get("text/plain", "")
            txt = tp if isinstance(tp, list) else [str(tp)]
        for line in txt:
            if pat.search(line) and re.search(r"\d\.\d+", line):
                s = line.strip()
                if s not in seen:
                    seen.add(s)
                    print(f"OUT  cell{i}: {s[:220]}")

